// ── 시간 왜곡 (기본 효과) ──────────────────────────────────────────
private _updateTimeWarp(api: GameSceneAPI): void {
  const now = Date.now();
  if (now - this.lastFreezeTime < GUMI_PARAMS.freezeCooldown) return;

  const { player, poops, scene } = api;
  const activePoops = (poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
    .filter(p => p.active && !this.frozenPoops.has(p));

  // 가장 가까운 순으로 정렬 후 반경 내 최대 N개 선택
  const nearTargets = activePoops
    .map(p => ({
      poop: p,
      dist: Phaser.Math.Distance.Between(player.x, player.y, p.x, p.y),
    }))
    .filter(({ dist }) => dist < GUMI_PARAMS.nearMissRadius)
    .sort((a, b) => a.dist - b.dist)
    .slice(0, GUMI_PARAMS.freezeCount);

  if (nearTargets.length === 0) return;

  this.lastFreezeTime = now;
  this._spawnWarpRipple(player.x, player.y, scene);

  for (const { poop } of nearTargets) {
    this._freezePoop(poop, scene);
  }
}

private _freezePoop(poop: Phaser.Physics.Arcade.Sprite, scene: Phaser.Scene): void {
  const body = poop.body as Phaser.Physics.Arcade.Body;
  if (!body) return;

  const originalVY = body.velocity.y;
  body.setVelocityY(0);
  poop.setTint(0x88ddff);
  this.frozenPoops.add(poop);

  // 동결 이펙트: 파란 글로우 링
  const ring = scene.add.graphics().setDepth(205);
  ring.lineStyle(2, 0x88ddff, 0.9);
  ring.strokeCircle(0, 0, 14);
  ring.setPosition(poop.x, poop.y);
  scene.tweens.add({
    targets: ring,
    scaleX: 1.8,
    scaleY: 1.8,
    alpha: 0,
    duration: GUMI_PARAMS.freezeDuration,
    ease: 'Quad.easeOut',
    onComplete: () => ring.destroy(),
  });

  scene.time.delayedCall(GUMI_PARAMS.freezeDuration, () => {
    this.frozenPoops.delete(poop);
    if (!poop.active || !poop.body) return;
    (poop.body as Phaser.Physics.Arcade.Body).setVelocityY(originalVY);
    poop.clearTint();
  });
}

private _spawnWarpRipple(x: number, y: number, scene: Phaser.Scene): void {
  ensureGlowDot(scene);

  // 확산 링 2개 (시간 왜곡 파문)
  for (let i = 0; i < 2; i++) {
    const ring = scene.add.graphics().setDepth(204);
    ring.lineStyle(2.5 - i, 0xaaddff, 0.85 - i * 0.25);
    ring.strokeCircle(0, 0, 18 + i * 8);
    ring.setPosition(x, y);
    scene.tweens.add({
      targets: ring,
      scaleX: 2.5,
      scaleY: 2.5,
      alpha: 0,
      delay: i * 80,
      duration: 380,
      ease: 'Quad.easeOut',
      onComplete: () => ring.destroy(),
    });
  }

  // 중앙 섬광
  const flash = scene.add.image(x, y, 'glow_dot')
    .setDepth(206)
    .setBlendMode(Phaser.BlendModes.ADD)
    .setTint(0xaaddff)
    .setScale(0.6);
  scene.tweens.add({
    targets: flash,
    scale: 0,
    alpha: 0,
    duration: 250,
    ease: 'Quad.easeOut',
    onComplete: () => flash.destroy(),
  });
}

