    const flash = scene.add.image(x, y, 'glow_dot')
      .setDepth(206)
      .setBlendMode(Phaser.BlendModes.ADD)
      .setTint(0xaaddff)
      .setScale(0.6);
    scene.tweens.add({
      targets: flash,
      scale: 0,
      alpha: 0,
      duration: 250,
      ease: 'Quad.easeOut',
      onComplete: () => flash.destroy(),
    });
  }

  private spawnHitFlash(x: number, y: number, scene: Phaser.Scene): void {
    for (let i = 0; i < 6; i++) {
      const angle = (i / 6) * Math.PI * 2;
      const spark = scene.add.image(x, y, 'glow_dot')
        .setDepth(201)
        .setBlendMode(Phaser.BlendModes.ADD)
        .setTint(0xffd700)
        .setScale(0.3);
      scene.tweens.add({
        targets: spark,
        x: x + Math.cos(angle) * 25,
        y: y + Math.sin(angle) * 25,
        scale: 0,
        alpha: 0,
        duration: 300,
        ease: 'Quad.easeOut',
        onComplete: () => spark.destroy(),
      });
    }
  }

  override onDestroy(_api: GameSceneAPI): void {
    this.foxFires.forEach(f => { f.img.destroy(); f.core.destroy(); });
    this.foxFires = [];
    this.frozenPoops.clear();
  }
}

