import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';
import type PoolablePoopBase from '../objects/PoolablePoopBase';
import { ensureGlowDot } from '../utils/glowDot';
import { GUMI_PARAMS } from '../config/abilityParams';

const HIT_R = 18;

// 빨주노초파남보흰회 (검정은 ADD에서 안 보여 밝은 회색으로 대체)
const FOX_FIRE_COLORS = [
  0xff2200,  // 빨
  0xff7700,  // 주
  0xffee00,  // 노
  0x00cc44,  // 초
  0x0066ff,  // 파
  0x3300cc,  // 남
  0xaa00ff,  // 보
  0xffffff,  // 흰
  0xcccccc,  // 검(회색 대체)
];

interface FoxFire {
  img: Phaser.GameObjects.Image;
  core: Phaser.GameObjects.Graphics;
  x: number;
  y: number;
  baseVx: number;
  speedY: number;
  phase: number;
  freq: number;
  trailTimer: number;
  color: number;
}

/**
 * 구미 (UR) — 시간 왜곡 / 여우불 9개로 닿은 똥을 금똥으로 변환
 * 수치: GUMI_PARAMS 참조
 */
export class GumiAbility extends BaseAbility {
  private lastGumiScore = 0;
  private foxFires: FoxFire[] = [];
  private lastFreezeTime = 0;
  private frozenPoops = new Set<Phaser.Physics.Arcade.Sprite>();

  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % GUMI_PARAMS.foxFireInterval === 0 && score > this.lastGumiScore) {
      this.lastGumiScore = score;
      this.summonFoxFires(api);
    }
  }

  private summonFoxFires(api: GameSceneAPI): void {
    const { scene, player } = api;
    const N = GUMI_PARAMS.foxFireCount;
    ensureGlowDot(scene);

    for (let i = 0; i < N; i++) {
      const ringAngle = (i / N) * Math.PI * 2;
      const x = player.x + Math.cos(ringAngle) * 55;
      const y = player.y + Math.sin(ringAngle) * 55;
      const color = FOX_FIRE_COLORS[i];

      const img = scene.add.image(x, y, 'glow_dot')
        .setDepth(200)
        .setBlendMode(Phaser.BlendModes.ADD)
        .setTint(color)
        .setScale(0.45);

      const core = scene.add.graphics().setDepth(202);
      core.fillStyle(0xffffff, 1);
      core.fillCircle(0, 0, 5);
      core.fillStyle(color, 0.85);
      core.fillCircle(0, 0, 3.5);
      core.setPosition(x, y);

      this.foxFires.push({
        img, core, x, y, color,
        baseVx:     Phaser.Math.FloatBetween(-3.5, 3.5),
        speedY:     Phaser.Math.FloatBetween(4.5, 7.5),
        phase:      Phaser.Math.FloatBetween(0, Math.PI * 2),
        freq:       Phaser.Math.FloatBetween(0.07, 0.17),
        trailTimer: 0,
      });
    }
  }

  override onUpdate(api: GameSceneAPI): void {
    this._updateTimeWarp(api);
    if (this.foxFires.length === 0) return;

    const { scene } = api;
    const activePoops = api.poops.getChildren().filter(
      p => (p as Phaser.Physics.Arcade.Sprite).active
    ) as Phaser.Physics.Arcade.Sprite[];

    const remaining: FoxFire[] = [];

    for (const fire of this.foxFires) {
      fire.trailTimer++;
      fire.x += fire.baseVx + Math.sin(fire.phase + fire.trailTimer * fire.freq) * 6;
      fire.y -= fire.speedY;
      fire.img.setPosition(fire.x, fire.y);
      fire.core.setPosition(fire.x, fire.y);

      // 3프레임마다 빛 꼬리 잔상
      if (fire.trailTimer % 3 === 0) {
        const trail = scene.add.image(fire.x, fire.y, 'glow_dot')
          .setDepth(199)
          .setBlendMode(Phaser.BlendModes.ADD)
          .setTint(fire.color)
          .setScale(0.22);
        scene.tweens.add({
          targets: trail,
          scale: 0,
          alpha: 0,
          duration: 200,
          ease: 'Quad.easeOut',
          onComplete: () => trail.destroy(),
        });
      }

      if (fire.y < -30 || fire.x < -30 || fire.x > 430) {
        fire.img.destroy();
        fire.core.destroy();
        continue;
      }

      let hit = false;
      for (const poop of activePoops) {
        const dx = fire.x - poop.x;
        const dy = fire.y - poop.y;
        if (dx * dx + dy * dy < HIT_R * HIT_R) {
          const px = poop.x;
          const py = poop.y;
          (poop as unknown as PoolablePoopBase).recycle();
          api.spawnGoldPoopAt(px, py);
          this.spawnHitFlash(px, py, scene);
          fire.img.destroy();
          fire.core.destroy();
          hit = true;
          break;
        }
      }

      if (!hit) remaining.push(fire);
    }

    this.foxFires = remaining;
  }

  // ── 시간 왜곡 (기본 효과) ──────────────────────────────────────────
  private _updateTimeWarp(api: GameSceneAPI): void {
    const now = Date.now();
    if (now - this.lastFreezeTime < GUMI_PARAMS.freezeCooldown) return;

    const { player, poops, scene } = api;
    const activePoops = (poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
      .filter(p => p.active && !this.frozenPoops.has(p));

    // 가장 가까운 순으로 정렬 후 반경 내 최대 N개 선택
    const nearTargets = activePoops
      .map(p => ({
        poop: p,
        dist: Phaser.Math.Distance.Between(player.x, player.y, p.x, p.y),
      }))
      .filter(({ dist }) => dist < GUMI_PARAMS.nearMissRadius)
      .sort((a, b) => a.dist - b.dist)
      .slice(0, GUMI_PARAMS.freezeCount);

    if (nearTargets.length === 0) return;

    this.lastFreezeTime = now;
    this._spawnWarpRipple(player.x, player.y, scene);

    for (const { poop } of nearTargets) {
      this._freezePoop(poop, scene);
    }
  }

  private _freezePoop(poop: Phaser.Physics.Arcade.Sprite, scene: Phaser.Scene): void {
    const body = poop.body as Phaser.Physics.Arcade.Body;
    if (!body) return;

    const originalVY = body.velocity.y;
    body.setVelocityY(0);
    poop.setTint(0x88ddff);
    this.frozenPoops.add(poop);

    // 동결 이펙트: 파란 글로우 링
    const ring = scene.add.graphics().setDepth(205);
    ring.lineStyle(2, 0x88ddff, 0.9);
    ring.strokeCircle(0, 0, 14);
    ring.setPosition(poop.x, poop.y);
    scene.tweens.add({
      targets: ring,
      scaleX: 1.8,
      scaleY: 1.8,
      alpha: 0,
      duration: GUMI_PARAMS.freezeDuration,
      ease: 'Quad.easeOut',
      onComplete: () => ring.destroy(),
    });

    scene.time.delayedCall(GUMI_PARAMS.freezeDuration, () => {
      this.frozenPoops.delete(poop);
      if (!poop.active || !poop.body) return;
      (poop.body as Phaser.Physics.Arcade.Body).setVelocityY(originalVY);
      poop.clearTint();
    });
  }

  private _spawnWarpRipple(x: number, y: number, scene: Phaser.Scene): void {
    ensureGlowDot(scene);

    // 확산 링 2개 (시간 왜곡 파문)
    for (let i = 0; i < 2; i++) {
      const ring = scene.add.graphics().setDepth(204);
      ring.lineStyle(2.5 - i, 0xaaddff, 0.85 - i * 0.25);
      ring.strokeCircle(0, 0, 18 + i * 8);
      ring.setPosition(x, y);
      scene.tweens.add({
        targets: ring,
        scaleX: 2.5,
        scaleY: 2.5,
        alpha: 0,
        delay: i * 80,
        duration: 380,
        ease: 'Quad.easeOut',
        onComplete: () => ring.destroy(),
      });
    }

    // 중앙 섬광
    const flash = scene.add.image(x, y, 'glow_dot')
      .setDepth(206)
      .setBlendMode(Phaser.BlendModes.ADD)
      .setTint(0xaaddff)
      .setScale(0.6);
    scene.tweens.add({
      targets: flash,
      scale: 0,
      alpha: 0,
      duration: 250,
      ease: 'Quad.easeOut',
      onComplete: () => flash.destroy(),
    });
  }

  private spawnHitFlash(x: number, y: number, scene: Phaser.Scene): void {
    for (let i = 0; i < 6; i++) {
      const angle = (i / 6) * Math.PI * 2;
      const spark = scene.add.image(x, y, 'glow_dot')
        .setDepth(201)
        .setBlendMode(Phaser.BlendModes.ADD)
        .setTint(0xffd700)
        .setScale(0.3);
      scene.tweens.add({
        targets: spark,
        x: x + Math.cos(angle) * 25,
        y: y + Math.sin(angle) * 25,
        scale: 0,
        alpha: 0,
        duration: 300,
        ease: 'Quad.easeOut',
        onComplete: () => spark.destroy(),
      });
    }
  }

  override onDestroy(_api: GameSceneAPI): void {
    this.foxFires.forEach(f => { f.img.destroy(); f.core.destroy(); });
    this.foxFires = [];
    this.frozenPoops.clear();
  }
}

