1	import Phaser from 'phaser';
2	import { BaseAbility } from './BaseAbility';
3	import type { GameSceneAPI } from './types';
4	import type PoolablePoopBase from '../objects/PoolablePoopBase';
5	import { SENTINEL_PARAMS } from '../config/abilityParams';
6	
7	/**
8	 * 센티넬 (UR) — 보호막
9	 * ★0: 2개 시작 / 300점마다 충전 / 최대 3  / ★1: 2개 / 250점마다 / 최대 4
10	 * ★2: 3개 시작 / 200점마다 충전 / 최대 4  / ★3: 3개 / 150점마다 / 최대 5 + 흡수 시 연쇄 전기 3개 추가 제거
11	 * - UI: 붉은 공이 허리 주변 수평 궤도 공전 + 전기 파지직 (재사용 Graphics)
12	 */
13	export class SentinelAbility extends BaseAbility {
14	  private shieldCount = 0;
15	  private orbitDroplets: Phaser.GameObjects.Graphics[] = [];
16	  private orbitAngle = 0;
17	
18	  // ── 전기 스파크: persistent Graphics 재사용 (동적 생성 없음) ──
19	  private sparkGfx: Phaser.GameObjects.Graphics | null = null;
20	  private sparkTween: Phaser.Tweens.Tween | null = null;
21	  private sparkTimer = 0;
22	
23	  private static readonly ORBIT_SPEED   = 3.0;
24	  private static readonly ORBIT_RX      = 26;
25	  private static readonly ORBIT_RY      = 7;
26	  private static readonly ORBIT_WAIST_Y = 8;
27	  private static readonly RED           = 0xff2222;
28	  private static readonly RED_LIGHT     = 0xff6666;
29	
30	  override onCreate(api: GameSceneAPI): void {
31	    this.shieldCount = SENTINEL_PARAMS.startShields;
32	    this.spawnDroplets(api, SENTINEL_PARAMS.startShields);
33	    this.sparkGfx = api.scene.add.graphics().setDepth(96).setAlpha(0);
34	  }
35	
36	  override onScoreMilestone(score: number, api: GameSceneAPI): void {
37	    if (score % SENTINEL_PARAMS.chargeInterval === 0 && this.shieldCount < SENTINEL_PARAMS.maxShields) {
38	      this.shieldCount++;
39	      this.playShieldChargeEffect(api);
40	      this.spawnDroplets(api, 1);
41	    }
42	  }
43	
44	  override onHitPoop(api: GameSceneAPI): boolean {
45	    if (this.shieldCount > 0) {
46	      this.shieldCount--;
47	      this.scatterDroplets(api, 1);
48	      this.playShieldBreakEffect(api);
49	      this.zapNearbyPoops(api, 320);
50	      return true;
51	    }
52	    return false;
53	  }
54	
55	  override onUpdate(api: GameSceneAPI): void {
56	    if (this.orbitDroplets.length === 0) return;
57	
58	    const delta  = api.scene.game.loop.delta / 1000;
59	    const deltMs = api.scene.game.loop.delta;
60	    this.orbitAngle += SentinelAbility.ORBIT_SPEED * delta;
61	
62	    const cx    = api.player.x;
63	    const cy    = api.player.y + SentinelAbility.ORBIT_WAIST_Y;
64	    const total = this.orbitDroplets.length;
65	    const RX    = SentinelAbility.ORBIT_RX;
66	    const RY    = SentinelAbility.ORBIT_RY;
67	
68	    this.orbitDroplets.forEach((drop, i) => {
69	      if (!drop.active) return;
70	      const angle = this.orbitAngle + (i / total) * Math.PI * 2;
71	      const sinA  = Math.sin(angle);
72	
73	      drop.setPosition(cx + Math.cos(angle) * RX, cy + sinA * RY);
74	
75	      const t = (sinA + 1) / 2;
76	      drop.setScale(0.55 + 0.55 * t);
77	      drop.setAlpha(0.35 + 0.65 * t);
78	      drop.setDepth(sinA > 0 ? 101 : 89);
79	    });
80	
81	    // 전기 파지직: 250ms마다 persistent sparkGfx를 clear+redraw
82	    this.sparkTimer += deltMs;
83	    if (this.sparkTimer >= 250) {
84	      this.sparkTimer = 0;
85	      this.redrawSparks(api);
86	    }
87	  }
88	
89	  // ─────────────────────────────────────────────────────────────
90	  // 리소스 정리 (게임 오버 시 GameScene에서 호출)
91	  // ─────────────────────────────────────────────────────────────
92	
93	  override onDestroy(_api: GameSceneAPI): void {
94	    this.sparkTween?.stop();
95	    this.sparkGfx?.destroy();
96	    this.orbitDroplets.forEach(drop => drop.destroy());
97	  }
98	
99	  // ─────────────────────────────────────────────────────────────
100	  // 전기 스파크 (재사용 Graphics)
101	  // ─────────────────────────────────────────────────────────────
102	
103	  /** persistent sparkGfx를 clear 후 몸+공 스파크를 새로 그리고 alpha tween */
104	  private redrawSparks(api: GameSceneAPI): void {
105	    const g = this.sparkGfx;
106	    if (!g?.active) return;
107	
108	    g.clear();
109	    g.setAlpha(1);
110	    this.sparkTween?.stop();
111	
112	    // 몸 주변 스파크 (굵게)
113	    const ba    = Phaser.Math.FloatBetween(0, Math.PI * 2);
114	    const br    = Phaser.Math.FloatBetween(18, 34);
115	    this.drawSparkLine(g, api.player.x + Math.cos(ba) * br, api.player.y + Math.sin(ba) * br * 0.6, 2.5, 10);
116	
117	    // 공 주변 스파크 (가늘게, 40% 확률 per droplet)
118	    this.orbitDroplets.forEach(drop => {
119	      if (drop.active && drop.alpha > 0.5 && Math.random() < 0.4) {
120	        this.drawSparkLine(g, drop.x, drop.y, 1, 7);
121	      }
122	    });
123	
124	    this.sparkTween = api.scene.tweens.add({
125	      targets: g,
126	      alpha: 0,
127	      duration: 200,
128	      ease: 'Quad.easeOut',
129	    });
130	  }
131	
132	  /** 전달받은 Graphics에 지그재그 라인을 직접 그림 (새 객체 생성 없음) */
133	  private drawSparkLine(g: Phaser.GameObjects.Graphics, ox: number, oy: number, thickness: number, segLen: number): void {
134	    const color = Math.random() < 0.6 ? 0xff3333 : 0xff7744;
135	    g.lineStyle(thickness, color, 1);
136	    g.beginPath();
137	    let px = ox + Phaser.Math.Between(-5, 5);
138	    let py = oy + Phaser.Math.Between(-5, 5);
139	    g.moveTo(px, py);
140	    const segs = Phaser.Math.Between(2, 4);
141	    for (let j = 0; j < segs; j++) {
142	      px += Phaser.Math.Between(-segLen, segLen);
143	      py += Phaser.Math.Between(-segLen, segLen);
144	      g.lineTo(px, py);
145	    }
146	    g.strokePath();
147	  }
148	
149	  // ─────────────────────────────────────────────────────────────
150	  // 방울 관리
151	  // ─────────────────────────────────────────────────────────────
152	
153	  private spawnDroplets(api: GameSceneAPI, count: number): void {
154	    const scene = api.scene;
155	    for (let i = 0; i < count; i++) {
156	      const g = scene.add.graphics().setDepth(95);
157	      this.drawDroplet(g);
158	      g.setPosition(api.player.x, api.player.y + SentinelAbility.ORBIT_WAIST_Y);
159	      g.setAlpha(0);
160	      this.orbitDroplets.push(g);
161	      scene.tweens.add({ targets: g, alpha: 1, scaleX: 1, scaleY: 1, duration: 350, delay: i * 50, ease: 'Back.easeOut' });
162	    }
163	  }
164	
165	  private scatterDroplets(api: GameSceneAPI, count: number): void {
166	    const scene   = api.scene;
167	    const removed = this.orbitDroplets.splice(0, count);
168	    removed.forEach(drop => {
169	      const angle = Phaser.Math.FloatBetween(0, Math.PI * 2);
170	      const dist  = Phaser.Math.FloatBetween(30, 55);
171	      scene.tweens.add({
172	        targets: drop,
173	        x: drop.x + Math.cos(angle) * dist,
174	        y: drop.y + Math.sin(angle) * dist,
175	        alpha: 0, scaleX: 0.1, scaleY: 0.1,
176	        duration: 120, ease: 'Quad.easeIn',
177	        onComplete: () => drop.destroy(),
178	      });
179	    });
180	  }
181	
182	  private drawDroplet(g: Phaser.GameObjects.Graphics): void {
183	    g.clear();
184	    g.fillStyle(SentinelAbility.RED, 0.22);
185	    g.fillCircle(0, 0, 15);
186	    g.fillStyle(SentinelAbility.RED, 0.4);
187	    g.fillCircle(0, 0, 10);
188	    g.fillStyle(SentinelAbility.RED, 0.95);
189	    g.fillCircle(0, 0, 7);
190	    g.fillStyle(0xffffff, 0.5);
191	    g.fillCircle(-2, -2.5, 2.5);
192	  }
193	
194	  // ─────────────────────────────────────────────────────────────
195	  // 파장 범위 내 똥 제거
196	  // ─────────────────────────────────────────────────────────────
197	
198	  private zapNearbyPoops(api: GameSceneAPI, radius: number): void {
199	    const cx = api.player.x;
200	    const cy = api.player.y;
201	    const r2 = radius * radius;
202	
203	    const targets = (api.poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
204	      .filter(p => p.active && (p.x - cx) ** 2 + (p.y - cy) ** 2 <= r2);
205	
206	    if (targets.length === 0) return;
207	
208	    const positions = targets.map(p => ({ x: p.x, y: p.y }));
209	    targets.forEach(p => (p as PoolablePoopBase).recycle());
210	
211	    // 단일 Graphics에 모든 위치 그리기 → 3회 redraw로 지글 효과
212	    const zapG = api.scene.add.graphics().setDepth(155);
213	    let frame   = 0;
214	
215	    const drawZapFrame = () => {
216	      zapG.clear();
217	      positions.forEach(pos => {
218	        zapG.fillStyle(SentinelAbility.RED, 0.55 - frame * 0.12);
219	        zapG.fillCircle(pos.x, pos.y, 10);
220	        const sparks = Phaser.Math.Between(2, 3);
221	        for (let i = 0; i < sparks; i++) {
222	          this.drawSparkLine(
223	            zapG,
224	            pos.x + Phaser.Math.Between(-8, 8),
225	            pos.y + Phaser.Math.Between(-8, 8),
226	            Phaser.Math.FloatBetween(1.5, 2.5),
227	            10
228	          );
229	        }
230	      });
231	      frame++;
232	    };
233	
234	    drawZapFrame();
235	
236	    // 60ms, 120ms 후 redraw, 200ms 후 fade+destroy
237	    [60, 120].forEach(delay => {
238	      api.scene.time.delayedCall(delay, () => {
239	        if (!api.scene.sys.isActive() || !zapG.active) return;
240	        drawZapFrame();
241	      });
242	    });
243	
244	    api.scene.time.delayedCall(180, () => {
245	      if (!api.scene.sys.isActive() || !zapG.active) return;
246	      api.scene.tweens.add({
247	        targets: zapG, alpha: 0, duration: 200,
248	        ease: 'Quad.easeOut',
249	        onComplete: () => zapG.destroy(),
250	      });
251	    });
252	  }
253	
254	  // ─────────────────────────────────────────────────────────────
255	  // 이펙트
256	  // ─────────────────────────────────────────────────────────────
257	
258	  private playShieldBreakEffect(api: GameSceneAPI): void {
259	    const scene = api.scene;
260	    const cx    = api.player.x;
261	    const cy    = api.player.y;
262	
263	    scene.cameras.main.flash(200, 255, 40, 40, true);
264	
265	    [{ delay: 0, maxScale: 4.3 }, { delay: 80, maxScale: 3.4 }].forEach(({ delay, maxScale }) => {
266	      const ring = scene.add.graphics().setDepth(150);
267	      ring.lineStyle(2.5, SentinelAbility.RED_LIGHT, 0.9);
268	      ring.strokeEllipse(0, 0, 74, 98);
269	      ring.setPosition(cx, cy);
270	      scene.tweens.add({
271	        targets: ring, scaleX: maxScale, scaleY: maxScale, alpha: 0,
272	        duration: 500, delay, ease: 'Quad.easeOut',
273	        onComplete: () => ring.destroy(),
274	      });
275	    });
276	
277	    const fill = scene.add.graphics().setDepth(149);
278	    fill.fillStyle(SentinelAbility.RED, 0.28);
279	    fill.fillEllipse(0, 0, 74, 98);
280	    fill.setPosition(cx, cy);
281	    scene.tweens.add({
282	      targets: fill, alpha: 0, duration: 180, ease: 'Quad.easeOut',
283	      onComplete: () => fill.destroy(),
284	    });
285	
286	    for (let i = 0; i < 8; i++) {
287	      const angle = (i / 8) * Math.PI * 2 + Phaser.Math.FloatBetween(-0.25, 0.25);
288	      const speed = Phaser.Math.FloatBetween(40, 95);
289	      const w = Phaser.Math.Between(5, 12);
290	      const h = Phaser.Math.Between(2, 5);
291	      const shard = scene.add.graphics().setDepth(152);
292	      shard.fillStyle(SentinelAbility.RED, 1);
293	      shard.fillRect(-w / 2, -h / 2, w, h);
294	      shard.setPosition(cx, cy);
295	      shard.setRotation(angle);
296	      scene.tweens.add({
297	        targets: shard,
298	        x: cx + Math.cos(angle) * speed, y: cy + Math.sin(angle) * speed,
299	        alpha: 0, rotation: angle + Phaser.Math.FloatBetween(-1, 1),
300	        duration: Phaser.Math.Between(270, 440), ease: 'Quad.easeOut',
301	        onComplete: () => shard.destroy(),
302	      });
303	    }
304	  }
305	
306	  private playShieldChargeEffect(api: GameSceneAPI): void {
307	    const scene = api.scene;
308	    const cx    = api.player.x;
