import Phaser from 'phaser';
import { BaseAbility } from './BaseAbility';
import type { GameSceneAPI } from './types';
import type PoolablePoopBase from '../objects/PoolablePoopBase';
import { ensureGlowDot } from '../utils/glowDot';
import { GUMI_PARAMS } from '../config/abilityParams';

const HIT_R = 18;

// 빨주노초파남보흰회 (검정은 ADD에서 안 보여 밝은 회색으로 대체)
const FOX_FIRE_COLORS = [
  0xff2200,  // 빨
  0xff7700,  // 주
  0xffee00,  // 노
  0x00cc44,  // 초
  0x0066ff,  // 파
  0x3300cc,  // 남
  0xaa00ff,  // 보
  0xffffff,  // 흰
  0xcccccc,  // 검(회색 대체)
];

interface FoxFire {
  img: Phaser.GameObjects.Image;
  core: Phaser.GameObjects.Graphics;
  x: number;
  y: number;
  baseVx: number;
  speedY: number;
  phase: number;
  freq: number;
  trailTimer: number;
  color: number;
}

/**
 * 구미 (UR) — 자기장(기본) / 여우불 9개로 닿은 똥을 금똥으로 변환(특수)
 * 수치: GUMI_PARAMS 참조
 */
export class GumiAbility extends BaseAbility {
  private lastGumiScore = 0;
  private foxFires: FoxFire[] = [];

  // 자기장: 슬로우 중인 똥 → 원본 velocityY
  private slowedPoops = new Map<Phaser.Physics.Arcade.Sprite, number>();
  private fieldGfx: Phaser.GameObjects.Graphics | null = null;

  // ── 자기장 초기화 ──────────────────────────────────────────────────
  override onCreate(api: GameSceneAPI): void {
    const { scene, player } = api;

    this.fieldGfx = scene.add.graphics().setDepth(85);
    this._drawFieldShape();
    this.fieldGfx.setPosition(player.x, player.y);

    // 박동 효과 (Sine 루프)
    scene.tweens.add({
      targets: this.fieldGfx,
      alpha: { from: 0.35, to: 0.8 },
      duration: 1100,
      yoyo: true,
      repeat: -1,
      ease: 'Sine.easeInOut',
    });
  }

  /** 자기장 모양 1회 드로우 (센티넬 방어막과 동일 크기 기준) */
  private _drawFieldShape(): void {
    const g = this.fieldGfx;
    if (!g) return;
    g.clear();
    // 외곽 글로우
    g.lineStyle(7, 0xcc88ff, 0.1);
    g.strokeEllipse(0, 0, 84, 110);
    // 메인 아웃라인 (센티넬 방어막: 74×98)
    g.lineStyle(1.5, 0xbb77ff, 0.75);
    g.strokeEllipse(0, 0, 74, 98);
    // 내부 보조선
    g.lineStyle(0.8, 0xddaaff, 0.3);
    g.strokeEllipse(0, 0, 58, 76);
  }

  // ── 자기장 업데이트 (매 프레임) ───────────────────────────────────
  private _updateMagneticField(api: GameSceneAPI): void {
    const { player, poops } = api;
    const r2 = GUMI_PARAMS.fieldRadius * GUMI_PARAMS.fieldRadius;

    // 그래픽 위치를 플레이어에 고정
    if (this.fieldGfx?.active) {
      this.fieldGfx.setPosition(player.x, player.y);
    }

    const allPoops = poops.getChildren() as Phaser.Physics.Arcade.Sprite[];

    for (const poop of allPoops) {
      // 비활성화된 똥: 슬로우 기록 제거
      if (!poop.active) {
        this.slowedPoops.delete(poop);
        continue;
      }

      const body = poop.body as Phaser.Physics.Arcade.Body | null;
      if (!body) continue;

      const dx = poop.x - player.x;
      const dy = poop.y - player.y;
      const inField = dx * dx + dy * dy < r2;

      if (inField && !this.slowedPoops.has(poop)) {
        // 진입: 원본 속도 저장 후 절반으로
        const originalVY = body.velocity.y;
        this.slowedPoops.set(poop, originalVY);
        body.setVelocityY(originalVY * GUMI_PARAMS.slowFactor);
        poop.setTint(0xcc99ff);
      } else if (!inField && this.slowedPoops.has(poop)) {
        // 이탈: 원본 속도 복원
        const originalVY = this.slowedPoops.get(poop)!;
        this.slowedPoops.delete(poop);
        body.setVelocityY(originalVY);
        poop.clearTint();
      }
    }
  }

  // ── 특수 능력: 여우불 ─────────────────────────────────────────────
  override onScoreMilestone(score: number, api: GameSceneAPI): void {
    if (score % GUMI_PARAMS.foxFireInterval === 0 && score > this.lastGumiScore) {
      this.lastGumiScore = score;
      this.summonFoxFires(api);
    }
  }

  private summonFoxFires(api: GameSceneAPI): void {
    const { scene, player } = api;
    const N = GUMI_PARAMS.foxFireCount;
    ensureGlowDot(scene);

    for (let i = 0; i < N; i++) {
      const ringAngle = (i / N) * Math.PI * 2;
      const x = player.x + Math.cos(ringAngle) * 55;
      const y = player.y + Math.sin(ringAngle) * 55;
      const color = FOX_FIRE_COLORS[i];

      const img = scene.add.image(x, y, 'glow_dot')
        .setDepth(200)
        .setBlendMode(Phaser.BlendModes.ADD)
        .setTint(color)
        .setScale(0.45);

      const core = scene.add.graphics().setDepth(202);
      core.fillStyle(0xffffff, 1);
      core.fillCircle(0, 0, 5);
      core.fillStyle(color, 0.85);
      core.fillCircle(0, 0, 3.5);
      core.setPosition(x, y);

      this.foxFires.push({
        img, core, x, y, color,
        baseVx:     Phaser.Math.FloatBetween(-3.5, 3.5),
        speedY:     Phaser.Math.FloatBetween(4.5, 7.5),
        phase:      Phaser.Math.FloatBetween(0, Math.PI * 2),
        freq:       Phaser.Math.FloatBetween(0.07, 0.17),
        trailTimer: 0,
      });
    }
  }

  override onUpdate(api: GameSceneAPI): void {
    this._updateMagneticField(api);

    if (this.foxFires.length === 0) return;

    const { scene } = api;
    const activePoops = api.poops.getChildren().filter(
      p => (p as Phaser.Physics.Arcade.Sprite).active
    ) as Phaser.Physics.Arcade.Sprite[];

    const remaining: FoxFire[] = [];

    for (const fire of this.foxFires) {
      fire.trailTimer++;
      fire.x += fire.baseVx + Math.sin(fire.phase + fire.trailTimer * fire.freq) * 6;
      fire.y -= fire.speedY;
      fire.img.setPosition(fire.x, fire.y);
      fire.core.setPosition(fire.x, fire.y);

      // 3프레임마다 빛 꼬리 잔상
      if (fire.trailTimer % 3 === 0) {
        const trail = scene.add.image(fire.x, fire.y, 'glow_dot')
          .setDepth(199)
          .setBlendMode(Phaser.BlendModes.ADD)
          .setTint(fire.color)
          .setScale(0.22);
        scene.tweens.add({
          targets: trail,
          scale: 0,
          alpha: 0,
          duration: 200,
          ease: 'Quad.easeOut',
          onComplete: () => trail.destroy(),
        });
      }

      if (fire.y < -30 || fire.x < -30 || fire.x > 430) {
        fire.img.destroy();
        fire.core.destroy();
        continue;
      }

      let hit = false;
      for (const poop of activePoops) {
        const dx = fire.x - poop.x;
        const dy = fire.y - poop.y;
        if (dx * dx + dy * dy < HIT_R * HIT_R) {
          const px = poop.x;
          const py = poop.y;
          // 슬로우 기록 제거 후 변환
          this.slowedPoops.delete(poop);
          (poop as unknown as PoolablePoopBase).recycle();
          api.spawnGoldPoopAt(px, py);
          this.spawnHitFlash(px, py, scene);
          fire.img.destroy();
          fire.core.destroy();
          hit = true;
          break;
        }
      }

      if (!hit) remaining.push(fire);
    }

    this.foxFires = remaining;
  }

  private spawnHitFlash(x: number, y: number, scene: Phaser.Scene): void {
    for (let i = 0; i < 6; i++) {
      const angle = (i / 6) * Math.PI * 2;
      const spark = scene.add.image(x, y, 'glow_dot')
        .setDepth(201)
        .setBlendMode(Phaser.BlendModes.ADD)
        .setTint(0xffd700)
        .setScale(0.3);
      scene.tweens.add({
        targets: spark,
        x: x + Math.cos(angle) * 25,
        y: y + Math.sin(angle) * 25,
        scale: 0,
        alpha: 0,
        duration: 300,
        ease: 'Quad.easeOut',
        onComplete: () => spark.destroy(),
      });
    }
  }

  override onDestroy(_api: GameSceneAPI): void {
    this.foxFires.forEach(f => { f.img.destroy(); f.core.destroy(); });
    this.foxFires = [];
    this.slowedPoops.clear();
    this.fieldGfx?.destroy();
    this.fieldGfx = null;
  }
}

