interface FoxFire {
  img: Phaser.GameObjects.Image;
  core: Phaser.GameObjects.Graphics;
  x: number;
  y: number;
  baseVx: number;
  speedY: number;
  phase: number;
  freq: number;
  trailTimer: number;
  color: number;
}

interface TailObj {
  gfx: Phaser.GameObjects.Graphics;
  baseAngle: number; // 기준 각도 (radians)
  swayPhase: number; // 흔들림 위상 (랜덤)
  swayFreq: number;  // 흔들림 속도 (radians/s)
  color: number;
}

/**
 * 구미 (UR) — 꼬리 9개 무적(기본) / 여우불 금똥 변환(특수)
 * 수치: GUMI_PARAMS 참조
 */
export class GumiAbility extends BaseAbility {
  // ── 여우불 (특수 능력) ─────────────────────────────────────────────
