  private foxFires: FoxFire[] = [];

  // ── 꼬리 스택 (기본 효과) ─────────────────────────────────────────
  private tailCount = 0;
  private lastTailScore = 0;
  private invincibleActive = false;
  private invincibleElapsed = 0;
  private tails: TailObj[] = [];
  private invincibleTween: Phaser.Tweens.Tween | null = null;

  // ── 꼬리 형태 드로우 ──────────────────────────────────────────────
  /** 꼬리를 로컬 +Y 방향(tip = 아래)으로 그림 — rotation으로 방향 지정 */
  private _drawTailShape(g: Phaser.GameObjects.Graphics, color: number): void {
    g.clear();
    // 외곽 솜털 글로우
    g.fillStyle(color, 0.18);
    g.fillEllipse(0, 0, 22, 48);
    // 주 몸통
