      targets: gfx,
      scale: 1,
      duration: 380,
      ease: 'Back.easeOut',
    });

    this.tails.push({
      gfx,
      baseAngle,
      swayPhase: Phaser.Math.FloatBetween(0, Math.PI * 2),
      swayFreq:  Phaser.Math.FloatBetween(1.2, 2.8),
      color,
    });
