// ── 꼬리 추가 ─────────────────────────────────────────────────────
private _addTail(api: GameSceneAPI): void {
  const { scene, player } = api;
  ensureGlowDot(scene);

  const i         = this.tailCount;
  const color     = FOX_FIRE_COLORS[i] ?? 0xffffff;
  const baseAngle = TAIL_ANGLE_ORDER[i] ?? (270 * Math.PI / 180);
  const originX   = player.x;
  const originY   = player.y + TAIL_ORIGIN_Y;

  const segs: TailSegImg[] = [];
  for (const seg of TAIL_SEGS) {
    const img = scene.add.image(
      originX + Math.cos(baseAngle) * seg.dist,
      originY + Math.sin(baseAngle) * seg.dist,
      'glow_dot',
    )
      .setDepth(TAIL_DEPTH)
      .setBlendMode(Phaser.BlendModes.ADD)
      .setTint(color)
      .setScale(0)
      .setAlpha(0.92);
    segs.push({ img, offsetDist: seg.dist, baseScale: seg.scale });
  }

  // 등장 애니메이션 (base → tip 순차)
  segs.forEach((si, idx) => {
    scene.tweens.add({
      targets: si.img,
      scale: si.baseScale,
      delay: idx * 45,
      duration: 320,
      ease: 'Back.easeOut',
    });
  });

  this.tails.push({
    segs,
    baseAngle,
    swayPhase: Phaser.Math.FloatBetween(0, Math.PI * 2),
    swayFreq:  Phaser.Math.FloatBetween(1.2, 2.8),
    color,
  });
  this.tailCount++;

  if (this.tailCount >= GUMI_PARAMS.maxTails) {
    this._triggerInvincibility(api);
  }
}

// ── 꼬리 살랑 업데이트 (매 프레임) ───────────────────────────────
private _updateTailPositions(api: GameSceneAPI): void {
  const { player, scene } = api;
  const time    = scene.time.now * 0.001;
  const originX = player.x;
  const originY = player.y + TAIL_ORIGIN_Y;

  for (const tail of this.tails) {
    const sway  = Math.sin(time * tail.swayFreq + tail.swayPhase) * SWAY_AMP;
    const angle = tail.baseAngle + sway;
    for (const si of tail.segs) {
      if (!si.img.active) continue;
      si.img.setPosition(
        originX + Math.cos(angle) * si.offsetDist,
        originY + Math.sin(angle) * si.offsetDist,
      );
    }
  }
}

