1	import Phaser from 'phaser';
2	import { BaseAbility } from './BaseAbility';
3	import type { GameSceneAPI } from './types';
4	import type PoolablePoopBase from '../objects/PoolablePoopBase';
5	import { ensureGlowDot } from '../utils/glowDot';
6	import { GUMI_PARAMS } from '../config/abilityParams';
7	
8	const HIT_R = 18;
9	
10	// 꼬리가 시작되는 Y 오프셋 (플레이어 중심 기준, 양수=아래=발 쪽)
11	const TAIL_ORIGIN_Y = 10;
12	const SWAY_AMP      = 0.28; // 흔들림 진폭 (radians)
13	
14	// 꼬리 체인: 세그먼트 수, 간격, 스케일 (지렁이 파동)
15	const NUM_SEGS   = 14;   // 꼬리 세그먼트 수 (14 × 5px = 70px)
16	const STEP_DIST  = 5;    // 세그먼트 간 거리 (px)
17	const PHASE_STEP = 0.35; // 세그먼트마다 위상 어긋남
18	// 타원형: base·tip 가늘고 5~6번째 가장 두꺼움
19	const SEG_SCALES = [0.10, 0.20, 0.30, 0.37, 0.41, 0.42, 0.41, 0.36, 0.30, 0.22, 0.15, 0.10, 0.06, 0.03];
20	
21	// 꼬리 depth (플레이어 depth 5보다 낮아야 몸통 뒤에 숨음)
22	const TAIL_DEPTH = 3;
23	
24	// 여우불 9색
25	const FOX_FIRE_COLORS = [
26	  0xff2200,  // 빨
27	  0xff7700,  // 주
28	  0xffee00,  // 노
29	  0x00cc44,  // 초
30	  0x0066ff,  // 파
31	  0x3300cc,  // 남
32	  0xaa00ff,  // 보
33	  0xffffff,  // 흰
34	  0xcccccc,  // 검(회색 대체)
35	];
36	
37	// 꼬리 등장 순서: 1번째=흰, 2~8번째=빨주노초파남보, 9번째=검
38	const TAIL_COLORS = [
39	  0xffffff,  // 1번째: 흰
40	  0xff2200,  // 2번째: 빨
41	  0xff7700,  // 3번째: 주
42	  0xffee00,  // 4번째: 노
43	  0x00cc44,  // 5번째: 초
44	  0x0066ff,  // 6번째: 파
45	  0x3300cc,  // 7번째: 남
46	  0xaa00ff,  // 8번째: 보
47	  0xcccccc,  // 9번째: 검
48	];
49	
50	// 꼬리 배치 각도: 왼쪽(190°)→오른쪽(350°) 순서 — 빨주노초파남보흰검 순으로 공간 배치
51	const TAIL_ANGLE_ORDER = [190, 210, 230, 250, 270, 290, 310, 330, 350]
52	  .map(deg => deg * Math.PI / 180);
53	
54	interface FoxFire {
55	  img: Phaser.GameObjects.Image;
56	  core: Phaser.GameObjects.Graphics;
57	  x: number;
58	  y: number;
59	  baseVx: number;
60	  speedY: number;
61	  phase: number;
62	  freq: number;
63	  trailTimer: number;
64	  color: number;
65	}
66	
67	interface TailSegImg {
68	  img: Phaser.GameObjects.Image;
69	  baseScale: number;
70	}
71	
72	interface TailObj {
73	  segs: TailSegImg[];
74	  baseAngle: number;
75	  swayPhase: number;
76	  swayFreq: number;
77	  color: number;
78	}
79	
80	/**
81	 * 구미 (UR) — 꼬리 9개 무적(기본) / 여우불 금똥 변환(특수)
82	 * 수치: GUMI_PARAMS 참조
83	 */
84	export class GumiAbility extends BaseAbility {
85	  // ── 여우불 (특수 능력) ─────────────────────────────────────────────
86	  private lastGumiScore = 0;
87	  private foxFires: FoxFire[] = [];
88	
89	  // ── 꼬리 스택 (기본 효과) ─────────────────────────────────────────
90	  private tailCount = 0;
91	  private lastTailScore = 0;
92	  private invincibleActive = false;
93	  private invincibleElapsed = 0;
94	  private tails: TailObj[] = [];
95	
96	  // ── 플레이어 depth 설정 (꼬리가 몸통 뒤에 렌더링되도록) ──────────
97	  override onCreate(api: GameSceneAPI): void {
98	    api.player.setDepth(5);
99	  }
100	
101	  // ── 꼬리 추가 ─────────────────────────────────────────────────────
102	  private _addTail(api: GameSceneAPI): void {
103	    const { scene, player } = api;
104	    ensureGlowDot(scene);
105	
106	    const i         = this.tailCount;
107	    const color     = FOX_FIRE_COLORS[i] ?? 0xffffff;
108	    const baseAngle = TAIL_ANGLE_ORDER[i] ?? (270 * Math.PI / 180);
109	    const originX   = player.x;
110	    const originY   = player.y + TAIL_ORIGIN_Y;
111	
112	    const segs: TailSegImg[] = [];
113	    for (let s = 0; s < NUM_SEGS; s++) {
114	      const img = scene.add.image(
115	        originX + Math.cos(baseAngle) * (STEP_DIST * (s + 1)),
116	        originY + Math.sin(baseAngle) * (STEP_DIST * (s + 1)),
117	        'glow_dot',
118	      )
119	        .setDepth(TAIL_DEPTH)
120	        .setBlendMode(Phaser.BlendModes.ADD)
121	        .setTint(color)
122	        .setScale(0)
123	        .setAlpha(0.92);
124	      segs.push({ img, baseScale: SEG_SCALES[s] ?? 0.08 });
125	    }
126	
127	    // 등장 애니메이션 (base → tip 순차)
128	    segs.forEach((si, idx) => {
129	      scene.tweens.add({
130	        targets: si.img,
131	        scale: si.baseScale,
132	        delay: idx * 40,
133	        duration: 300,
134	        ease: 'Back.easeOut',
135	      });
136	    });
137	
138	    this.tails.push({
139	      segs,
140	      baseAngle,
141	      swayPhase: Phaser.Math.FloatBetween(0, Math.PI * 2),
142	      swayFreq:  Phaser.Math.FloatBetween(1.4, 2.8),
143	      color,
144	    });
145	    this.tailCount++;
146	
147	    if (this.tailCount >= GUMI_PARAMS.maxTails) {
148	      this._triggerInvincibility(api);
149	    }
150	  }
151	
152	  // ── 꼬리 지렁이 파동 업데이트 (매 프레임) ────────────────────────
153	  private _updateTailPositions(api: GameSceneAPI): void {
154	    const { player, scene } = api;
155	    const time    = scene.time.now * 0.001;
156	    const originX = player.x;
157	    const originY = player.y + TAIL_ORIGIN_Y;
158	
159	    for (const tail of this.tails) {
160	      let px = originX;
161	      let py = originY;
162	
163	      for (let s = 0; s < tail.segs.length; s++) {
164	        const si = tail.segs[s];
165	        if (!si.img.active) continue;
166	
167	        // 뿌리는 진폭 0, 끝으로 갈수록 진폭 증가 (지렁이 파동)
168	        const amp   = SWAY_AMP * (s / (NUM_SEGS - 1));
169	        const sway  = Math.sin(time * tail.swayFreq + tail.swayPhase + s * PHASE_STEP) * amp;
170	        const angle = tail.baseAngle + sway;
171	
172	        px += Math.cos(angle) * STEP_DIST;
173	        py += Math.sin(angle) * STEP_DIST;
174	        si.img.setPosition(px, py);
175	      }
176	    }
177	  }
178	
179	  // ── 점수 마일스톤 ─────────────────────────────────────────────────
180	  override onScoreMilestone(score: number, api: GameSceneAPI): void {
181	    // 여우불 (특수)
182	    if (score % GUMI_PARAMS.foxFireInterval === 0 && score > this.lastGumiScore) {
183	      this.lastGumiScore = score;
184	      this.summonFoxFires(api);
185	    }
186	    // 꼬리 추가 (기본) — 무적 중 누적 금지
187	    if (score % GUMI_PARAMS.tailInterval === 0 && score > this.lastTailScore && !this.invincibleActive) {
188	      this.lastTailScore = score;
189	      this._addTail(api);
190	    }
191	  }
192	
193	  // ── 무적 발동 ─────────────────────────────────────────────────────
194	  private _triggerInvincibility(api: GameSceneAPI): void {
195	    const { player, scene } = api;
196	    this.invincibleActive  = true;
197	    this.invincibleElapsed = 0;
198	
199	    // 꼬리 확대
200	    this.tails.forEach(t => {
201	      t.segs.forEach(si => {
202	        scene.tweens.add({
203	          targets: si.img,
204	          scale: si.baseScale * 1.5,
205	          duration: 320,
206	          ease: 'Back.easeOut',
207	        });
208	      });
209	    });
210	
211	    // 9색 버스트
212	    ensureGlowDot(scene);
213	    for (let i = 0; i < 9; i++) {
214	      const angle = (i / 9) * Math.PI * 2;
215	      const spark = scene.add.image(player.x, player.y, 'glow_dot')
216	        .setDepth(210)
217	        .setBlendMode(Phaser.BlendModes.ADD)
218	        .setTint(FOX_FIRE_COLORS[i])
219	        .setScale(0.6);
220	      scene.tweens.add({
221	        targets: spark,
222	        x: player.x + Math.cos(angle) * 65,
223	        y: player.y + Math.sin(angle) * 65,
224	        scale: 0, alpha: 0, duration: 520,
225	        ease: 'Quad.easeOut',
226	        onComplete: () => spark.destroy(),
227	      });
228	    }
229	  }
230	
231	  // ── 무적 카운트다운 ───────────────────────────────────────────────
232	  private _updateInvincibility(api: GameSceneAPI): void {
233	    this.invincibleElapsed += api.scene.game.loop.delta;
234	    if (this.invincibleElapsed >= GUMI_PARAMS.invincibleDuration) {
235	      this._endInvincibility(api);
236	    }
237	  }
238	
239	  // ── 무적 종료 ─────────────────────────────────────────────────────
240	  private _endInvincibility(api: GameSceneAPI): void {
241	    const { player, scene } = api;
242	
243	    this.invincibleActive = false;
244	    player.setAlpha(1);
245	
246	    // 꼬리 사라짐
247	    this.tails.forEach(t => {
248	      t.segs.forEach(si => {
249	        scene.tweens.add({
250	          targets: si.img, alpha: 0, scale: 0,
251	          duration: 380, ease: 'Quad.easeIn',
252	          onComplete: () => si.img.destroy(),
253	        });
254	      });
255	    });
256	    this.tails       = [];
257	    this.tailCount   = 0;
258	    this.lastTailScore = api.score; // 무적 중 지나친 마일스톤 역추적 방지
259	
260	    this._spawnBreakEffect(api);
261	    this._zapAllPoops(api);
262	  }
263	
264	  // ── 무적 종료 파열 이펙트 (센티넬 방어막 파열 스타일, 황금색) ────
265	  private _spawnBreakEffect(api: GameSceneAPI): void {
266	    const { player, scene } = api;
267	    const cx = player.x;
268	    const cy = player.y;
269	
270	    scene.cameras.main.flash(200, 255, 200, 50, true);
271	
272	    // 확산 링 2겹
273	    [{ delay: 0, maxScale: 4.3 }, { delay: 80, maxScale: 3.4 }].forEach(({ delay, maxScale }) => {
274	      const ring = scene.add.graphics().setDepth(150);
275	      ring.lineStyle(2.5, 0xffcc44, 0.9);
276	      ring.strokeEllipse(0, 0, 74, 98);
277	      ring.setPosition(cx, cy);
278	      scene.tweens.add({
279	        targets: ring, scaleX: maxScale, scaleY: maxScale, alpha: 0,
280	        duration: 500, delay, ease: 'Quad.easeOut',
281	        onComplete: () => ring.destroy(),
282	      });
283	    });
284	
285	    // 내부 섬광
286	    const fill = scene.add.graphics().setDepth(149);
287	    fill.fillStyle(0xffcc44, 0.25);
288	    fill.fillEllipse(0, 0, 74, 98);
289	    fill.setPosition(cx, cy);
290	    scene.tweens.add({
291	      targets: fill, alpha: 0, duration: 180, ease: 'Quad.easeOut',
292	      onComplete: () => fill.destroy(),
293	    });
294	
295	    // 황금 파편 8개
296	    for (let i = 0; i < 8; i++) {
297	      const angle = (i / 8) * Math.PI * 2 + Phaser.Math.FloatBetween(-0.25, 0.25);
298	      const speed = Phaser.Math.FloatBetween(40, 95);
299	      const w     = Phaser.Math.Between(5, 12);
300	      const h     = Phaser.Math.Between(2, 5);
301	      const shard = scene.add.graphics().setDepth(152);
302	      shard.fillStyle(0xffcc44, 1);
303	      shard.fillRect(-w / 2, -h / 2, w, h);
304	      shard.setPosition(cx, cy);
305	      shard.setRotation(angle);
306	      scene.tweens.add({
307	        targets: shard,
308	        x: cx + Math.cos(angle) * speed,
309	        y: cy + Math.sin(angle) * speed,
310	        alpha: 0, rotation: angle + Phaser.Math.FloatBetween(-1, 1),
311	        duration: Phaser.Math.Between(270, 440), ease: 'Quad.easeOut',
312	        onComplete: () => shard.destroy(),
313	      });
314	    }
315	  }
316	
317	  // ── 반경 내 똥 전부 제거 ──────────────────────────────────────────
318	  private _zapAllPoops(api: GameSceneAPI): void {
319	    const { player, poops, scene } = api;
320	    const r  = GUMI_PARAMS.zapRadius;
321	    const r2 = r * r;
322	
323	    (poops.getChildren() as Phaser.Physics.Arcade.Sprite[])
324	      .filter(p => p.active && (p.x - player.x) ** 2 + (p.y - player.y) ** 2 <= r2)
325	      .forEach(p => (p as unknown as PoolablePoopBase).recycle());
326	
327	    ensureGlowDot(scene);
328	
329	    // 황금 확산 링 2겹
330	    for (let i = 0; i < 2; i++) {
331	      const ring = scene.add.graphics().setDepth(212);
332	      ring.lineStyle(3 - i, 0xffcc44, 0.9 - i * 0.3);
333	      ring.strokeCircle(0, 0, 20);
334	      ring.setPosition(player.x, player.y);
335	      scene.tweens.add({
336	        targets: ring, scaleX: r / 20, scaleY: r / 20, alpha: 0,
337	        delay: i * 80, duration: 560, ease: 'Quad.easeOut',
338	        onComplete: () => ring.destroy(),
339	      });
340	    }
341	
342	    // 중앙 섬광
343	    const flash = scene.add.image(player.x, player.y, 'glow_dot')
344	      .setDepth(213)
345	      .setBlendMode(Phaser.BlendModes.ADD)
346	      .setTint(0xffee88)
347	      .setScale(1.8);
348	    scene.tweens.add({
349	      targets: flash, scale: 0, alpha: 0, duration: 460,
350	      ease: 'Quad.easeOut',
351	      onComplete: () => flash.destroy(),
352	    });
353	  }
354	
355	  // ── 피격: 무적 중이면 게임오버 방지 ──────────────────────────────
356	  override onHitPoop(_api: GameSceneAPI): boolean {
357	    return this.invincibleActive;
358	  }
359	
360	  // ── 여우불 소환 ───────────────────────────────────────────────────
361	  private summonFoxFires(api: GameSceneAPI): void {
362	    const { scene, player } = api;
363	    const N = GUMI_PARAMS.foxFireCount;
364	    ensureGlowDot(scene);
365	
366	    for (let i = 0; i < N; i++) {
367	      const ringAngle = (i / N) * Math.PI * 2;
368	      const x = player.x + Math.cos(ringAngle) * 55;
369	      const y = player.y + Math.sin(ringAngle) * 55;
370	      const color = FOX_FIRE_COLORS[i];
371	
372	      const img = scene.add.image(x, y, 'glow_dot')
373	        .setDepth(200)
374	        .setBlendMode(Phaser.BlendModes.ADD)
375	        .setTint(color)
376	        .setScale(0.45);
377	
378	      const core = scene.add.graphics().setDepth(202);
379	      core.fillStyle(0xffffff, 1);
380	      core.fillCircle(0, 0, 5);
381	      core.fillStyle(color, 0.85);
382	      core.fillCircle(0, 0, 3.5);
383	      core.setPosition(x, y);
384	
385	      this.foxFires.push({
386	        img, core, x, y, color,
387	        baseVx:     Phaser.Math.FloatBetween(-3.5, 3.5),
388	        speedY:     Phaser.Math.FloatBetween(4.5, 7.5),
389	        phase:      Phaser.Math.FloatBetween(0, Math.PI * 2),
390	        freq:       Phaser.Math.FloatBetween(0.07, 0.17),
391	        trailTimer: 0,
392	      });
393	    }
394	  }
395	
396	  // ── 매 프레임 ─────────────────────────────────────────────────────
397	  override onUpdate(api: GameSceneAPI): void {
398	    this._updateTailPositions(api);
399	    if (this.invincibleActive) this._updateInvincibility(api);
400	
401	    if (this.foxFires.length === 0) return;
402	
403	    const { scene } = api;
404	    const activePoops = api.poops.getChildren().filter(
405	      p => (p as Phaser.Physics.Arcade.Sprite).active,
406	    ) as Phaser.Physics.Arcade.Sprite[];
407	
408	    const remaining: FoxFire[] = [];
409	
410	    for (const fire of this.foxFires) {
411	      fire.trailTimer++;
412	      fire.x += fire.baseVx + Math.sin(fire.phase + fire.trailTimer * fire.freq) * 6;
413	      fire.y -= fire.speedY;
414	      fire.img.setPosition(fire.x, fire.y);
415	      fire.core.setPosition(fire.x, fire.y);
416	
417	      if (fire.trailTimer % 3 === 0) {
418	        const trail = scene.add.image(fire.x, fire.y, 'glow_dot')
419	          .setDepth(199)
420	          .setBlendMode(Phaser.BlendModes.ADD)
421	          .setTint(fire.color)
422	          .setScale(0.22);
423	        scene.tweens.add({
424	          targets: trail, scale: 0, alpha: 0, duration: 200,
425	          ease: 'Quad.easeOut',
426	          onComplete: () => trail.destroy(),
427	        });
428	      }
429	
430	      if (fire.y < -30 || fire.x < -30 || fire.x > 430) {
431	        fire.img.destroy();
432	        fire.core.destroy();
433	        continue;
434	      }
435	
436	      let hit = false;
437	      for (const poop of activePoops) {
438	        const dx = fire.x - poop.x;
439	        const dy = fire.y - poop.y;
440	        if (dx * dx + dy * dy < HIT_R * HIT_R) {
441	          const px = poop.x;
442	          const py = poop.y;
443	          (poop as unknown as PoolablePoopBase).recycle();
444	          api.spawnGoldPoopAt(px, py);
445	          this.spawnHitFlash(px, py, scene);
446	          fire.img.destroy();
447	          fire.core.destroy();
448	          hit = true;
449	          break;
450	        }
451	      }
452	
453	      if (!hit) remaining.push(fire);
454	    }
455	
456	    this.foxFires = remaining;
457	  }
458	
459	  private spawnHitFlash(x: number, y: number, scene: Phaser.Scene): void {
460	    for (let i = 0; i < 6; i++) {
461	      const angle = (i / 6) * Math.PI * 2;
462	      const spark = scene.add.image(x, y, 'glow_dot')
463	        .setDepth(201)
464	        .setBlendMode(Phaser.BlendModes.ADD)
465	        .setTint(0xffd700)
466	        .setScale(0.3);
467	      scene.tweens.add({
468	        targets: spark,
469	        x: x + Math.cos(angle) * 25,
470	        y: y + Math.sin(angle) * 25,
471	        scale: 0, alpha: 0, duration: 300,
472	        ease: 'Quad.easeOut',
473	        onComplete: () => spark.destroy(),
474	      });
475	    }
476	  }
477	
478	  override onDestroy(api: GameSceneAPI): void {
479	    if (this.invincibleActive) {
480	      api.player.setAlpha(1);
481	    }
482	    api.player.setDepth(0); // player depth 원복
483	    this.foxFires.forEach(f => { f.img.destroy(); f.core.destroy(); });
484	    this.foxFires = [];
485	    this.tails.forEach(t => t.segs.forEach(si => si.img.destroy()));
486	    this.tails = [];
487	  }
488	}
